WITH base AS (SELECT extract(year FROM e.data_final)::int AS ano,r.nome_categoria,r.idade_range, (r.data_nascimento<=e.data_final AND extract(year FROM e.data_final)-extract(year FROM r.data_nascimento) BETWEEN 0 AND 120) IS TRUE AS nascimento FROM public.tb_resultados r JOIN public.tb_evento_corridas e USING(id_evento) WHERE e.pais='BR' AND ((e.data_final>=DATE '2025-01-01' AND e.data_final<DATE '2026-01-01') OR(e.data_final>=DATE '2026-01-01' AND e.data_final<DATE '2026-10-01')) AND r.status_final=0 AND r.homologado AND r.concluinte),grupos AS(SELECT ano,coalesce(nome_categoria,'(sem categoria)') AS categoria,idade_range::text AS faixa,nascimento,count(*) AS participacoes FROM base GROUP BY ano,nome_categoria,idade_range,nascimento) SELECT jsonb_build_object('coletado_em',current_timestamp,'geral_f_socio',(SELECT jsonb_agg(to_jsonb(g)) FROM grupos g WHERE upper(categoria) LIKE '%GERAL%F%SOCIO%'),'sem_idade_top',(SELECT jsonb_agg(to_jsonb(g)) FROM (SELECT * FROM grupos WHERE faixa IS NULL AND NOT nascimento ORDER BY participacoes DESC LIMIT 12)g),'resumo',(SELECT jsonb_agg(to_jsonb(z)) FROM(SELECT ano,sum(participacoes) AS total,sum(participacoes) FILTER(WHERE nascimento) AS nascimento,sum(participacoes) FILTER(WHERE NOT nascimento AND faixa IS NOT NULL) AS somente_faixa,sum(participacoes) FILTER(WHERE NOT nascimento AND faixa IS NULL) AS desconhecidos FROM grupos GROUP BY ano)z)) AS payload